(function(root,f){const m=f();if(typeof module==='object'&&module.exports)module.exports=m;else root.obAccessibility=m})(this,function(){'use strict';const defaults={schema:1,palette:'standard',text:'normal',pointer:'normal'},values={palette:['standard','contrast','protan','deutan','tritan'],text:['normal','large','largest'],pointer:['normal','large','largest']};function normalize(raw){const result={...defaults};if(raw&&typeof raw==='object')for(const key of Object.keys(values))if(values[key].includes(raw[key]))result[key]=raw[key];return result}function load(storage){try{return normalize(JSON.parse(storage.getItem('ob.accessibility')||'{}'))}catch(e){return normalize(null)}}function save(storage,raw){const next=normalize(raw);storage.setItem('ob.accessibility',JSON.stringify(next));return next}function apply(doc,raw){const next=normalize(raw);for(const k of Object.keys(values))doc.documentElement.dataset[k]=next[k];return next}return {defaults,normalize,load,save,apply,values}});
